import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation using a bit array and multiple hash functions.

    The bit array size and number of hash functions are calculated based on the expected
    number of items and the desired false positive rate. 
    The hash functions are constructed using Python's hashlib.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.bit_array_size = self._calculate_bit_array_size(expected_items, false_positive_rate)
        self.num_hash_functions = self._calculate_num_hash_functions(self.bit_array_size, expected_items)

        self.bit_array = [0] * self.bit_array_size

    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """Calculate optimal size of the bit array."""
        size = -(n * math.log(p)) / (math.log(2) ** 2)
        return int(math.ceil(size))

    def _calculate_num_hash_functions(self, m: int, n: int) -> int:
        """Calculate optimal number of hash functions."""
        k = (m / n) * math.log(2)
        return int(math.ceil(k))

    def _hash(self, item: str, seed: int) -> int:
        """Create a hash of the item using a specific seed."""
        hash_object = hashlib.md5((item + str(seed)).encode())
        return int(hash_object.hexdigest(), 16) % self.bit_array_size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.num_hash_functions):
            index = self._hash(item, i)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        for i in range(self.num_hash_functions):
            index = self._hash(item, i)
            if self.bit_array[index] == 0:
                return False
        return True

