    positive rates based on specified parameters.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = max(expected_items, 1)
        self.false_positive_rate = max(false_positive_rate, 0) if false_positive_rate < 1 else 1

        self.bit_array_size = self._calculate_bit_array_size(self.expected_items, self.false_positive_rate)
        self.num_hash_functions = self._calculate_num_hash_functions(self.bit_array_size, self.expected_items)

        self.bit_array = [0] * self.bit_array_size

    def _calculate_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal size for the bit array."""
        size = -(n * math.log(p)) / (math.log(2) ** 2)
        return int(math.ceil(size))

    def _calculate_num_hash_functions(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return 0 if n == 0 else int(math.ceil((m / n) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash value for the item using a seed."""
        hash_object = hashlib.md5((item + str(seed)).encode())
        return int(hash_object.hexdigest(), 16) % self.bit_array_size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.num_hash_functions):
            index = self._hash(item, i)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is present in the Bloom Filter."""
        return all(self.bit_array[self._hash(item, i)] for i in range(self.num_hash_functions))

